import { MetadataRoute } from 'next';
import { API_HOST } from '@/lib/api';

export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const baseUrl = 'https://www.trayago.in';

  // Base list of core platform pages
  const staticPages: MetadataRoute.Sitemap = [
    { url: `${baseUrl}/`, lastModified: new Date(), changeFrequency: 'daily' as const, priority: 1.0 },
    { url: `${baseUrl}/live`, lastModified: new Date(), changeFrequency: 'daily' as const, priority: 0.8 },
    { url: `${baseUrl}/pnr`, lastModified: new Date(), changeFrequency: 'daily' as const, priority: 0.8 },
    { url: `${baseUrl}/tracker`, lastModified: new Date(), changeFrequency: 'daily' as const, priority: 0.8 },
    { url: `${baseUrl}/ai-waitlist-rescue`, lastModified: new Date(), changeFrequency: 'weekly' as const, priority: 0.8 },
    { url: `${baseUrl}/split-journey`, lastModified: new Date(), changeFrequency: 'daily' as const, priority: 0.8 },
    { url: `${baseUrl}/news`, lastModified: new Date(), changeFrequency: 'daily' as const, priority: 0.8 },
    { url: `${baseUrl}/about`, lastModified: new Date(), changeFrequency: 'monthly' as const, priority: 0.7 },
    { url: `${baseUrl}/app`, lastModified: new Date(), changeFrequency: 'monthly' as const, priority: 0.7 },
    { url: `${baseUrl}/pricing`, lastModified: new Date(), changeFrequency: 'monthly' as const, priority: 0.6 },
    { url: `${baseUrl}/terms`, lastModified: new Date(), changeFrequency: 'monthly' as const, priority: 0.5 },
    { url: `${baseUrl}/privacy`, lastModified: new Date(), changeFrequency: 'monthly' as const, priority: 0.5 },
    { url: `${baseUrl}/refund-policy`, lastModified: new Date(), changeFrequency: 'monthly' as const, priority: 0.5 },
    { url: `${baseUrl}/cookies`, lastModified: new Date(), changeFrequency: 'monthly' as const, priority: 0.5 },
    { url: `${baseUrl}/contact`, lastModified: new Date(), changeFrequency: 'monthly' as const, priority: 0.6 },
    { url: `${baseUrl}/rate-list`, lastModified: new Date(), changeFrequency: 'monthly' as const, priority: 0.5 }
    // PHASE_SEO-002: /flights, /hotels and /bus removed — next.config.mjs redirects
    // all three to / (307). Submitting redirecting URLs wastes crawl budget and is a
    // soft-404 signal. Re-add only if these routes become real, non-redirecting pages.
  ];

  // PHASE_SEO-004: Popular train live-status detail pages.
  // Deliberately HARDCODED to mirror POPULAR_TRAINS in live/page.tsx — these six
  // already have crawlable internal links from /live, so submitting them closes the
  // discovery loop. NOT generated from the trains table: ~67% of train names are NULL
  // and the train_schedule schema is unresolved, so bulk generation would publish
  // thin/inaccurate pages. Expand only via verified data, never by iteration.
  const popularTrainPages: MetadataRoute.Sitemap = [
    '12002', '12952', '12301', '12626', '12260', '12004',
  ].map((trainNo) => ({
    url: `${baseUrl}/live/${trainNo}`,
    lastModified: new Date(),
    changeFrequency: 'daily' as const,
    priority: 0.7,
  }));

  const newsArticlePages: MetadataRoute.Sitemap = [];

  // Fetch published news articles for dynamic sitemap inclusion
  try {
    const res = await fetch(`${API_HOST}/api/news/sitemap`, {
      next: { revalidate: 3600 }, // 1 hour revalidation
    }).catch(() => null);

    if (res && res.ok) {
      const json = await res.json();
      if (json.success && Array.isArray(json.data) && json.data.length > 0) {
        const publishedArticles = json.data;

        // Sort news by timestamp descending to find latest update date
        const dates = publishedArticles.map((a: any) => new Date(a.updatedAt || a.publishedAt).getTime());
        const latestTime = Math.max(...dates);

        // Update /news main listing lastModified
        const newsIndex = staticPages.findIndex((p) => p.url.endsWith('/news'));
        if (newsIndex > -1 && latestTime > 0) {
          staticPages[newsIndex].lastModified = new Date(latestTime);
        }

        // Add individual article URLs (normalized to lowercase matching article canonical URLs)
        for (const item of publishedArticles) {
          if (item.slug && typeof item.slug === 'string' && item.slug.trim() !== '') {
            const cleanSlug = item.slug.trim().toLowerCase();
            newsArticlePages.push({
              url: `${baseUrl}/news/${encodeURIComponent(cleanSlug)}`,
              lastModified: new Date(item.updatedAt || item.publishedAt || Date.now()),
              changeFrequency: 'weekly' as const,
              priority: 0.7,
            });
          }
        }
      }
    }
  } catch (err) {
    console.error('[SITEMAP] Failed to fetch published news for sitemap:', err);
  }

  return [...staticPages, ...popularTrainPages, ...newsArticlePages];
}
